"""React TSX source exporter for validated ALDOL UI specifications.

This generates code, not a running React application; host installs React and
bundles the generated module. All user values remain declarative React text.
"""
from __future__ import annotations
import json
from typing import Any
from . import core

TEMPLATE = r'''import * as React from "react";

// Generated by ALDOL UI MCP Alpha 0.3.2. Requires React and the generated CSS.
// Host controls authorization, gameplay, and network state. This is presentation only.
type NodeSpec = {type: string; [key: string]: any};
type UIAction = {type: "toggle" | "emit"; name: string; sourceLabel: string};
export type AldolUIProps = {
  mode?: "web" | "hud";
  values?: Record<string, string | number>;
  onAction?: (action: UIAction) => void;
};
const spec: NodeSpec = __SPEC__;
const panelDefaults: Record<string, boolean> = {};
function collect(n: NodeSpec) {
  if (n.type === "panel" && n.id) panelDefaults[n.id] = Boolean(n.hidden);
  (n.children || []).forEach(collect);
}
collect(spec);

export default function AldolUI({mode = "web", values = {}, onAction}: AldolUIProps) {
  const [expanded, setExpanded] = React.useState<Record<string, boolean>>({});
  function isOpen(n: NodeSpec) {
    return Object.prototype.hasOwnProperty.call(expanded, n.id) ? expanded[n.id] : !n.hidden;
  }
  function emit(n: NodeSpec) {
    const action = n.action;
    if (!action) return;
    if (action.type === "toggle") {
      const next = !isOpen({id: action.target, hidden: panelDefaults[action.target] ?? true});
      setExpanded(() => ({[action.target]: next}));
      onAction?.({type: "toggle", name: action.target, sourceLabel: n.label});
    } else if (action.type === "emit") {
      onAction?.({type: "emit", name: action.name, sourceLabel: n.label});
    }
  }
  function bound(n: NodeSpec, fallback: string | number): string | number {
    if (!n.bind || !Object.prototype.hasOwnProperty.call(values, n.bind)) return fallback;
    const value = values[n.bind];
    return typeof value === "string" || (typeof value === "number" && Number.isFinite(value)) ? value : fallback;
  }
  function make(n: NodeSpec, key: string): React.ReactNode {
    const children = n.children?.map((child: NodeSpec, index: number) => make(child, `${key}.${index}`));
    switch(n.type) {
      case "stack": return <div key={key} className="alui-stack">{children}</div>;
      case "row": return <div key={key} className={'alui-row' + (n.children?.every((child: NodeSpec) => child.type === 'button') ? ' alui-row--actions' : '')}>{children}</div>;
      case "grid": return <div key={key} className={"alui-grid alui-grid--"+(n.columns||2)} style={{"--alui-cols": n.columns || 2} as React.CSSProperties}>{children}</div>;
      case "panel": return <section key={key} className="alui-panel" id={n.id ? `alui-panel-${n.id}` : undefined}
        data-alui-id={n.id} data-alui-disclosure={n.id ? "true" : undefined}
        aria-label={n.label} hidden={n.id ? !isOpen(n) : Boolean(n.hidden)}>{children}</section>;
      case "card": return <section key={key} className="alui-card" aria-label={n.label}>{children}</section>;
      case "text": return <p key={key} className={'alui-text alui-text--' + (n.variant || 'normal')}>{bound(n,n.text)}</p>;
      case "badge": return <span key={key} className={'alui-badge alui-badge--' + (n.tone || 'neutral')}>{bound(n,n.text)}</span>;
      case "metric": return <div key={key} className={'alui-metric alui-metric--'+(n.tone||'neutral')}>
        <span className="alui-metric-label">{n.label}</span><strong className="alui-metric-value">{bound(n,n.value)}</strong></div>;
      case "notice": return <div key={key} className={'alui-notice alui-notice--'+(n.tone||'neutral')} role="note">{n.text}</div>;
      case "divider": return <hr key={key} className="alui-divider"/>;
      case "progress": {
        const raw = bound(n,n.value);
        const value = typeof raw === "number" ? Math.max(0,Math.min(n.max,raw)) : n.value;
        return <div key={key} className="alui-progress" role="progressbar" aria-label={n.label}
          aria-valuemin={0} aria-valuemax={n.max} aria-valuenow={value}>
          <span className="alui-progress-track"><span className="alui-progress-fill" style={{width:`${100*value/n.max}%`}}/></span></div>;
      }
      case "button": {
        const a = n.action;
        return <button key={key} type="button" className={'alui-button alui-button--'+(n.variant||'primary')}
          aria-controls={a?.type === 'toggle' ? `alui-panel-${a.target}`: undefined}
          aria-expanded={a?.type === 'toggle' ? isOpen({id:a.target,hidden:panelDefaults[a.target] ?? true}) : undefined}
          onClick={a ? () => emit(n) : undefined}>{n.label}</button>;
      }
      default: return null;
    }
  }
  return <main className={mode === "hud" ? "alui-hud-overlay" : "alui-app"} aria-label={__TITLE__}
    onKeyDown={event => {if(event.key === "Escape") setExpanded(current => Object.fromEntries(Object.keys(panelDefaults).map(id => [id, false])));}}>
    {make(spec, "0")}
  </main>;
}
'''


def export(spec_json: str) -> dict[str, Any]:
    spec = core._parse(spec_json)
    theme = {**core.PRESETS[spec.get('preset', 'forest')], **spec.get('theme', {})}
    button_text = max(('#000000', '#FFFFFF'), key=lambda color: core._contrast(color, theme['primary']))
    css = (core._css('alui-app', theme, button_text, False, spec.get('tokens'), spec.get('design')) + '\n' +
           core._css('alui-hud-overlay', theme, button_text, True, spec.get('tokens'), spec.get('design')))
    src = TEMPLATE.replace('__SPEC__', json.dumps(spec['root'], ensure_ascii=True))
    src = src.replace('__TITLE__', json.dumps(spec['title'], ensure_ascii=True))
    return {
        'target': 'react-tsx', 'component_tsx': src, 'css': css,
        'integration_notes': ('Compile with React, import CSS once; pass values to update presentation. '
                              'Listen onAction for host-side gameplay or web operations. '
                              'mode="hud" places DOM overlay above host game; no game scene provided.'),
        'warnings': core.audit(spec_json)['warnings'],
        'anti_slop': core.review(spec_json),
    }
